#include <iostream>

// Precondition: both readings are in [0, 1000].
int mean(int left, int right) {
    return (left + right) / 2; // Integer division drops fractions.
}

int main() {
    std::cout << "mean=" << mean(2, 8) << '\n';
}

#include <algorithm>
#include <iostream>

enum class Choice { mean, highest };

int dashboard(Choice choice, int a, int b) {
    if (choice == Choice::highest) return std::max(a, b);
    return (a + b) / 2;
}

int stale_report(Choice, int a, int b) {
    // Deliberate defect: this caller ignores the selected rule.
    return (a + b) / 2;
}

int main() {
    const auto choice = Choice::highest;
    std::cout << "dashboard=" << dashboard(choice, 1, 9) << '\n';
    std::cout << "stale report=" << stale_report(choice, 1, 9) << '\n';
}

#include <iostream>

struct Tally { int count; };

void add_to_copy(Tally value) { value.count += 3; }
void add_to_original(Tally& value) { value.count += 3; }
int observe(const Tally& value) { return value.count; }

int main() {
    Tally tally{5};
    add_to_copy(tally);
    std::cout << "after value=" << observe(tally) << '\n';
    add_to_original(tally);
    std::cout << "after reference=" << observe(tally) << '\n';
}

#include <algorithm>
#include <iostream>
#include <memory>

class Estimate {
public:
    virtual ~Estimate() = default;
    // Contract: a and b are both in [0, 1000].
    virtual int value(int a, int b) const = 0;
};
class Mean final : public Estimate {
public:
    int value(int a, int b) const override { return (a + b) / 2; }
};
class Highest final : public Estimate {
public:
    int value(int a, int b) const override { return std::max(a, b); }
};
int main() {
    std::unique_ptr<Estimate> rule = std::make_unique<Mean>();
    std::cout << "mean=" << rule->value(1, 9) << '\n';
    rule = std::make_unique<Highest>(); // Replace the owned rule.
    std::cout << "highest=" << rule->value(1, 9) << '\n';
}
